using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
[InitializeOnLoad] public static class StorybookAttributeValidation
{
 const string Out=StorybookAttributeAuthoring.Out;static bool running;static double start;
 static StorybookAttributeValidation(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool("SHARED_ATTRIBUTES_QA",false)){SessionState.SetBool("SHARED_ATTRIBUTES_QA",false);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",false);running=false;}};}
 static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;if(!EditorApplication.isPlayingOrWillChangePlaymode&&File.Exists(Out+"validate.request")){File.Delete(Out+"validate.request");File.WriteAllText(Out+"validation.txt","");UnityEditor.SceneManagement.EditorSceneManager.OpenScene(EditorBuildSettings.scenes.First(s=>s.enabled).path);SessionState.SetBool("SHARED_ATTRIBUTES_QA",true);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",true);EditorApplication.isPlaying=true;}if(EditorApplication.isPlaying&&SessionState.GetBool("SHARED_ATTRIBUTES_QA",false)&&!running&&GameManager.single&&GameplayCanvas.single){running=true;start=EditorApplication.timeSinceStartup;GameManager.single.StartCoroutine(Run());}if(running&&EditorApplication.timeSinceStartup-start>180){Check(false,"timeout");EditorApplication.isPlaying=false;}}
 static void Check(bool value,string message)=>File.AppendAllText(Out+"validation.txt",(value?"PASS ":"FAIL ")+message+"\n");
 static void Shot(string name){var t=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Out+name+".png",t.EncodeToPNG());UnityEngine.Object.Destroy(t);}
 static bool Hit(Button b){var r=(RectTransform)b.transform;var p=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center));var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=p},hits);return p.x>=0&&p.x<=Screen.width&&p.y>=0&&p.y<=Screen.height&&hits.Count>0&&hits[0].gameObject.GetComponentInParent<Button>()==b;}
 static void Panel(StorybookAttributePanel p,string label){Check(p&&p.values.Length==6&&p.add.Length==6,label+" has six shared cells");Check(p.add.All(Hit)&&Hit(p.fold),label+" all seven buttons visible and raycast correctly");Check(p.values.All(t=>t.cachedTextGenerator.vertexCount>=4),label+" all attribute values render");Check(p.contents.localScale.x==p.contents.localScale.y,label+" uniformly scaled contents");}
 static IEnumerator Run(){var intro=UnityEngine.Object.FindAnyObjectByType<CursedBookIntro>();while(intro&&intro.gameObject.activeSelf)yield return null;yield return new WaitForSecondsRealtime(.5f);
 foreach(var d in UnityEngine.Object.FindObjectsByType<DebugMenu>(FindObjectsInactive.Include,FindObjectsSortMode.None))d.enabled=false;var dev=UnityEngine.Object.FindAnyObjectByType<DeveloperOverlayUI>();if(dev)dev.gameObject.SetActive(false);
 var gc=GameplayCanvas.single;var gm=GameManager.single;gc.CancelInvoke("TryShowingXpBoosterNotification");gc.xpBoosterNotification.SetActive(false);gc.dailyCherriesPop.SetActive(false);gc.GetComponent<StorybookDailyReward>().enabled=false;TutorialManager.single.automatic=false;TutorialManager.single.view.Hide();for(int i=0;i<20;i++)if(!gm.HasSeenThis("Tutorial-"+i))gm.thingsSeenPermanent.Add("Tutorial-"+i);
 var home=gc.homeUI;gm.statPoints=6;gm.CalcPlayer();home.Refresh();Check(home.sharedAttributes,"Home binds shared prefab");
 foreach(var sz in new[]{new Vector2Int(1080,1920),new Vector2Int(768,1024),new Vector2Int(720,1440)}){
 StorybookEquipmentValidation.Resolution(sz.x,sz.y);yield return new WaitForSecondsRealtime(.4f);if(!home.attributesExpanded){home.ToggleAttributes();yield return new WaitForSecondsRealtime(.3f);}Panel(home.sharedAttributes,"Home "+sz);Check(Hit(home.battleButton),"Battle button unobstructed "+sz);yield return new WaitForEndOfFrame();Shot("home-expanded-"+sz.x+"x"+sz.y);
 home.collapseButton.onClick.Invoke();yield return new WaitForSecondsRealtime(.08f);Check(!home.attributeBody.blocksRaycasts,"Home fold animation blocks stat clicks");yield return new WaitForSecondsRealtime(.3f);Check(!home.attributeBody.gameObject.activeSelf&&!home.attributeBody.blocksRaycasts,"Home collapsed releases rays "+sz);yield return new WaitForEndOfFrame();Shot("home-collapsed-"+sz.x+"x"+sz.y);home.ToggleAttributes();yield return new WaitForSecondsRealtime(.3f);
 Router.single.InventoryButton();yield return new WaitForSecondsRealtime(2);var eq=gc.inventoryPanel.GetComponent<StorybookEquipmentUI>();if(!eq.attributesExpanded){eq.ToggleAttributes();yield return new WaitForSecondsRealtime(.3f);}Panel(eq.sharedAttributes,"Equipment "+sz);Check(home.statValues.Select(t=>t.text).SequenceEqual(eq.statValues.Select(t=>t.text)),"Same values in both hosts "+sz);Check(eq.sharedAttributes.points.font==home.sharedAttributes.points.font&&eq.sharedAttributes.add[0].GetComponent<Image>().sprite==home.sharedAttributes.add[0].GetComponent<Image>().sprite,"Same typography and button art "+sz);yield return new WaitForEndOfFrame();Shot("equipment-expanded-"+sz.x+"x"+sz.y);
 eq.ToggleAttributes();yield return new WaitForSecondsRealtime(.3f);Check(!eq.attributeBody.gameObject.activeSelf&&!eq.attributeBody.blocksRaycasts,"Equipment collapsed releases rays "+sz);yield return new WaitForEndOfFrame();Shot("equipment-collapsed-"+sz.x+"x"+sz.y);eq.back.onClick.Invoke();yield return new WaitForSecondsRealtime(2);
 }
 gm.statPoints=1;home.Refresh();int oldHp=gm.hpLevel;home.statButtons[0].onClick.Invoke();Check(gm.statPoints==0&&gm.hpLevel==oldHp+1&&home.statButtons.All(b=>!b.interactable),"Home last point updates cost level and buttons immediately");yield return new WaitForSecondsRealtime(.2f);Check(home.statButtons.All(b=>b.GetComponent<Image>().material.GetFloat("_DisabledUI")==1),"Home disabled buttons entirely greyscale");yield return new WaitForEndOfFrame();Shot("home-disabled");gm.statPoints=3;home.Refresh();yield return new WaitForSecondsRealtime(.2f);Check(home.statButtons.Select((b,i)=>b.interactable==home.CanBuy(i)).All(x=>x),"Home restores available stat buttons");
 Router.single.InventoryButton();yield return new WaitForSecondsRealtime(2);var equipment=gc.inventoryPanel.GetComponent<StorybookEquipmentUI>();if(!equipment.attributesExpanded){equipment.ToggleAttributes();yield return new WaitForSecondsRealtime(.3f);}gm.statPoints=1;equipment.RefreshStats();int oldDamage=gm.dmgLevel;equipment.statButtons[1].onClick.Invoke();Check(gm.statPoints==0&&gm.dmgLevel==oldDamage+1&&equipment.statButtons.All(b=>!b.interactable),"Equipment last point updates immediately");yield return new WaitForSecondsRealtime(.2f);Check(equipment.statButtons.All(b=>b.GetComponent<Image>().material.GetFloat("_DisabledUI")==1),"Equipment disabled buttons entirely greyscale");equipment.back.onClick.Invoke();yield return new WaitForSecondsRealtime(2);Check(home.pointsText.text.Contains("0")&&home.statValues[1].text==equipment.statValues[1].text,"Returning home refreshes points and values");
 File.AppendAllText(Out+"validation.txt","DONE\n");EditorApplication.isPlaying=false;
 }
}
